/* syrk.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* --------------------------------------------------------------------
 * Tunable kernel parameters
 * --------------------------------------------------------------------
 *
 * Blocking factor for the j-dimension in the SYRK kernel.  This helps
 * improve temporal locality when updating C[i][j] by working on small
 * blocks of the lower triangle at a time.  The value can be adjusted
 * at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DSYRK_J_BLOCK_SIZE=64 ...
 *
 * to better fit the target machine's cache hierarchy.
 */
#ifndef SYRK_J_BLOCK_SIZE
# define SYRK_J_BLOCK_SIZE 32
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  /* Local aliases with restrict-qualified pointers to help the
   * compiler assume that A and C do not alias each other.
   *
   * We use pointers to VLA types parametrized by the runtime sizes
   * (n, m) so that the compiler still knows the true row strides.
   */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  int i, j, k;

  /* Optimized SYRK kernel
   *
   * Original math:
   *   For i = 0..N-1, j = 0..i:
   *     C[i][j] = beta * C[i][j] +
   *               alpha * sum_{k=0..M-1} A[i][k] * A[j][k]
   *
   * Key optimizations:
   *  - Reorder loops to make the k-loop innermost so that A[i][k] and
   *    A[j][k] are accessed with unit stride (row-major layout), which
   *    greatly improves cache locality and enables efficient SIMD.
   *  - Fuse the beta scaling of C with the rank-k update so that each
   *    C[i][j] element is loaded and stored only once.
   *  - Tile the j-dimension with a tunable block size (SYRK_J_BLOCK_SIZE)
   *    to improve temporal locality within each row of C and among the
   *    A[j][:] rows involved in the update.
   *
   * The triangular update pattern (j <= i) is strictly preserved so the
   * upper part of C has exactly the same values as in the original code.
   */

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Pointers to the current row of C and A.  These stay fixed while
     * we sweep j (within the lower triangle) for this i.
     */
    DATA_TYPE *Ci        = C_[i];
    const DATA_TYPE *Ai  = A_[i];

    /* Number of columns (j indices) to update in this row (0..i). */
    int max_j_for_i = i + 1;

    /* Tile the j dimension.  For each i, we process j in blocks
     * [jb, j_end) ⊆ [0, i].
     */
    for (int jb = 0; jb < max_j_for_i; jb += SYRK_J_BLOCK_SIZE) {
      int j_end = jb + SYRK_J_BLOCK_SIZE;
      if (j_end > max_j_for_i)
        j_end = max_j_for_i;

      for (j = jb; j < j_end; j++) {
        const DATA_TYPE *Aj = A_[j];

        /* Apply beta scaling first (as in the original separate loop). */
        DATA_TYPE cij = Ci[j] * beta_;

        /* Compute the inner product of row i and row j of A.  The k-loop
         * is innermost, giving unit-stride access in both Ai and Aj.
         */
        DATA_TYPE sum = 0;
        for (k = 0; k < _PB_M; k++) {
          sum += Ai[k] * Aj[k];
        }

        /* Final update for C[i][j]. */
        Ci[j] = cij + alpha_ * sum;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
