 *   reduction loop.  This does not change the numerical algorithm.
 * --------------------------------------------------------------------- */
#ifndef SYRK_K_UNROLL
# define SYRK_K_UNROLL 4
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
