   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Local copies encourage the compiler to keep these scalars in registers. */
  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* BLAS PARAMS
   * TRANS = 'N'
   * UPLO  = 'L'
   * => Form  C := alpha*A*A**T + beta*C.
   * A is NxM, C is NxN (only the lower triangle of C is updated).
   */

#pragma scop
  /* Optimized formulation:
   *
   *   for i in 0..N-1
   *     for j in 0..i
   *       C[i][j] = beta*C[i][j]
   *                  + alpha * sum_{k=0}^{M-1} A[i][k] * A[j][k];
   *
   * Key changes compared to the original version:
   *
   * 1. Fused beta scaling with the rank-k update so that each C[i][j]
   *    element is loaded and stored exactly once, instead of once for
   *    the scaling plus once per inner k-iteration.
   *
   * 2. Made the reduction over k the innermost loop.  This yields:
   *      - Unit-stride access to A[i][k] and A[j][k] (row-major layout),
   *        which improves cache utilization and prefetch efficiency.
   *      - A simple, straight-line reduction that the compiler can
   *        easily vectorize and unroll.
   *
   * The arithmetic order for each individual C[i][j] is preserved:
   * we still perform C[i][j] *= beta first, then accumulate contributions
   * for k = 0..M-1 in increasing order.  Only the interleaving across
   * different (i,j) pairs changes, which does not affect correctness.
   */
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++) {
      /* Load once, apply beta, then accumulate the rank-k update in a
       * register before writing back. */
      DATA_TYPE cij = C[i][j] * beta_local;

      /* Pure reduction over k: no loop-carried dependencies, which allows
       * the compiler to safely vectorize and unroll this loop.  The GCC
       * pragmas are hints and do not affect semantics. */
#pragma GCC ivdep
#pragma GCC unroll SYRK_K_UNROLL
      for (k = 0; k < _PB_M; k++) {
        cij += alpha_local * A[i][k] * A[j][k];
      }

      C[i][j] = cij;
    }
  }
#pragma endscop
}


