  const int nPB = _PB_N;
  const int mPB = _PB_M;

  /* Local restrict-qualified views of the 2D arrays.
     This tells the compiler that C and A do not alias. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

#pragma scop
  /* Outer loop over rows of C (and A). */
  for (int i = 0; i < nPB; ++i)
  {
    DATA_TYPE *restrict Ci = C_[i];  /* Row i of C. */
    DATA_TYPE *restrict Ai = A_[i];  /* Row i of A. */

    /* We only update the lower triangular part: j <= i. */
    for (int j = 0; j <= i; ++j)
    {
      DATA_TYPE *restrict Aj = A_[j];  /* Row j of A. */

      /* Start from beta * C[i][j], just like the original kernel
         (which first scaled C, then accumulated). The accumulation
         over k is then done in a register variable. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Block the k-loop to improve cache locality when m is large. */
      for (int kk = 0; kk < mPB; kk += SYRK_TILE_K)
      {
        int kend = kk + SYRK_TILE_K;
        if (kend > mPB) kend = mPB;

        /* Innermost loop: contiguous access along A's second dimension.
           This is friendly for both cache and SIMD vectorization. */
        #pragma GCC ivdep
        for (int k = kk; k < kend; ++k)
        {
          cij += alpha_local * Ai[k] * Aj[k];
        }
      }

      /* Store the final result back to C. */
      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
