}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version notes:

   - The mathematical operation is:
       C := beta * C + alpha * A * A^T     (UPLO = 'L', only C[i][j] with j <= i)
     where A is n x m and C is n x n.

   - Compared to the original kernel:
       * We fuse the previous "scale by beta" loop with the main update,
         so each C[i][j] is loaded and stored only once.
       * For each (i,j) pair we compute a dot product over k:
             sum = Σ_k A[i][k] * A[j][k]
         and then perform:
             C[i][j] = beta * C[i][j] + alpha * sum;
         This reduces the number of floating-point multiplications by
         moving the multiplication by alpha outside the inner k-loop.
       * The inner-most loop now walks contiguously along the k dimension
         of both A[i][:] and A[j][:], improving spatial locality for A.
       * C[i][j] is kept in a scalar (register) during the k loop, avoiding
         repeated loads/stores of C inside the innermost loop.

   - The triangular access pattern (j <= i) and the mathematical result
     are preserved exactly.
*/
static void __attribute__((noinline))
kernel_syrk(int n, int m,
	    DATA_TYPE alpha,
	    DATA_TYPE beta,
	    DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
	    DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Local aliases (no qualifiers changed) for clarity.
     They also make it explicit we are working with n- and m-sized VLAs. */
  DATA_TYPE (*C_)[n] = C;
  DATA_TYPE (*A_)[m] = A;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  //BLAS PARAMS
  //TRANS = 'N'
  //UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  //A is NxM
  //C is NxN
#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci        = C_[i];   /* Row i of C */
    const DATA_TYPE *Ai  = A_[i];   /* Row i of A */

    /* Only lower-triangular part: j <= i */
    for (j = 0; j <= i; j++) {
      const DATA_TYPE *Aj = A_[j];  /* Row j of A */
      DATA_TYPE sum = (DATA_TYPE)0;

      /* Compute dot product between row i and row j of A:
           sum = Σ_k A[i][k] * A[j][k]
         This loop has good spatial locality on both Ai and Aj
         and is amenable to auto-vectorization.
      */
      for (k = 0; k < _PB_M; k++) {
        sum += Ai[k] * Aj[k];
      }

      /* Combine scaling by beta and rank-k update into a single
         load/compute/store on C[i][j]. */
      Ci[j] = beta_ * Ci[j] + alpha_ * sum;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
